class NomDependenciaEstructuraEscalar extends BaseNomDependenciaEstructuraEscalar {
	
	/**
     * Obtener un listado de los datos de las dependencias de estructura escalar dado un identificador de estructura escalar.
     * 
     * @param int $idestrucesc  	Identificador de la estructura escalar.
     * @return array Listado de los datos de las dependencias de estructuras escalares.
     */
    public static function obtenerListadoDependenciasEstructurasEscalares($idestrucesc) {
	
        //Devolviendo el listado de estructuras escalares en forma de arreglo.
        return Doctrine_Query::create()
				->select('de.iddependenciaestructuraescalar, de.idestructuraescalar, de.idestructuraescalaradyacente, ee.denominacion as denomestruraescalar')
				->from('NomDependenciaEstructuraEscalar de')
				->leftjoin('de.NomEstructuraEscalar ee on ee.idestructuraescalar = de.idestructuraescalaradyacente')
                ->where('de.idestructuraescalar = ?', array($idestrucesc))
                ->fetchArray();
    }
	
	/**
     * Obtener la dependencia de estructura escalar dado el identificador.
     * 
     * @param $iddepestrucesc        						Identificador de la dependencia de estructura escalar.
     * @return NomDependenciaEstructuraEscalar    	 		Objeto dependencia estructura escalar (clase del dominio).
     */
    public static function obtenerObjDependenciaEstructuraEscalarDadoId($iddepestrucesc) {
        return Doctrine::getTable('NomDependenciaEstructuraEscalar')->find($iddepestrucesc);
    }
}